mkdir -p $TMPDIR/q && cat > $TMPDIR/q/esc.py <<'EOF'
import re, glob, os, collections
D='/tmp/r2run-gpe_frrx/data/text'
pages=[]
for f in sorted(glob.glob(D+'/*.txt')):
    t=open(f,encoding='utf-8',errors='replace').read()
    for p in re.split(r'=== page \d+', t)[1:]:
        if 'Case Number' in p: pages.append((os.path.basename(f),p))
print('cases',len(pages))
def norm(s): return re.sub(r'\s+',' ',s)
def headline(rec):
    s=rec.replace('$$','$')
    m=re.search(r'\$\s?(\d{1,3}(?:,\s?\d{3})*(?:\.\d+)?|\d+(?:\.\d+)?)',s)
    if not m: return 0
    return float(re.sub(r'[,\s]','',m.group(1)))
esc=[];anyesc=0
for fn,p in pages:
    n=norm(p)
    m=re.search(r'civil penalty:(.*?)(Abstentions|Additional Information)',n,re.I|re.S)
    rec=m.group(1) if m else ''
    if re.search(r'ticket\s+escalation',rec,re.I):
        esc.append((fn,re.search(r'Case Number:\s*(\S+)',n).group(1),rec.strip(),headline(rec)))
    if re.search(r'ticket\s+escalation',n,re.I): anyesc+=1
print('escalation in recommendation:',len(esc),' anywhere on page:',anyesc)
c=collections.Counter(x[3] for x in esc)
for x in esc: print(x)
print(c.most_common())
EOF
python3 -I $TMPDIR/q/esc.py
